from pathlib import Path
import json
root=Path(__file__).parent
out=root/'dist'
manifest=json.loads((root/'.openai/hosting.json').read_text());manifest['static']={'directory':'dist'};(root/'.openai/hosting.json').write_text(json.dumps(manifest,indent=2))
origin='https://application-photo-lab.lucky-ocean-5746.chatgpt.site'
svg='<svg viewBox="0 0 48 48" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><rect x="7" y="5" width="34" height="38" rx="3"/><circle cx="24" cy="18" r="6"/><path d="M13 37c0-13 22-13 22 0"/></svg>'
header='<a class="skip" href="#main">Skip to tools</a><header><div class="header-inner"><a class="brand" href="/"><span class="brand-mark" aria-hidden="true">⌑</span>Photo Lab <small>EARLY RELEASE</small></a><nav aria-label="Main navigation"><a href="/">Image tools</a><a href="/help/">How it works</a><a href="/privacy/">Privacy</a></nav></div></header>'
footer='<footer><div class="footer-inner"><span>Application Photo Lab · Independent tools for your next application.</span><div class="footer-links"><a href="/about/">About</a><a href="/privacy/">Privacy</a><a href="/terms/">Terms</a><a href="/contact/">Contact</a></div></div></footer>'
def page(path,title,description,body,tool=None):
    dest=out/path/'index.html';dest.parent.mkdir(parents=True,exist_ok=True)
    canonical=origin+'/'+(path+'/' if path else '')
    dest.write_text(f'<!doctype html><html lang="en-IN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Photo Lab</title><meta name="description" content="{description}"><link rel="canonical" href="{canonical}"><meta name="theme-color" content="#255b43"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/style.css"></head><body'+(f' data-tool="{tool}"' if tool else '')+'>'+header+'<main id="main">'+body+'</main>'+footer+('<script type="module" src="/app.js"></script>' if tool else '')+'</body></html>')
faq='''<section class="help-grid"><div><span class="eyebrow">A little guidance</span><h2>Less trial and error.<br>More clarity.</h2><p class="small">Copy the requirements from your application portal. We check the file; you check that it looks right.</p><a class="text-link small" href="/help/">Read the preparation guide →</a></div><div><details><summary>What if my file cannot fit the size range?</summary><p>We test JPG quality settings from 100% down to 45% at your chosen dimensions. If none fit, we explain the problem. PNG does not have the same quality control. Try JPG if allowed, a different crop, or a better original. We never pad the file with meaningless bytes.</p></details><details><summary>Will my photo or signature be uploaded?</summary><p>The tools process images in your browser. The application code does not upload images, filenames, or previews. The hosting provider still receives ordinary page requests.</p></details><details><summary>Does passing mean the portal will accept it?</summary><p>No. We check format, pixel dimensions and byte size only. Readability, background, face position, photo age, DPI and other portal rules still need your review.</p></details></div></section>'''
for path,tool,label in [('', 'photo','photo'),('signature','signature','signature'),('checker','checker','image')]:
    check=tool=='checker'
    tabs='<div class="tabs" aria-label="Choose a tool">'+''.join(f'<a href="{url}"'+(' aria-current="page"' if tool==key else '')+f'>{text}</a>' for key,url,text in [('photo','/','Photo resizer'),('signature','/signature/','Signature resizer'),('checker','/checker/','Requirement checker')])+'</div>'
    heading='Check the file.<br><em>Know where it stands.</em>' if check else f'Your {label}. The right size.<br><em>One less thing to worry about.</em>'
    intro='Compare an image against your portal’s format, dimensions and file-size requirements.' if check else 'Prepare a clear, correctly sized image for your application. Free to use, with processing on your device.'
    fields=f'''<div class="subhead">02 / {'Requirements to check' if check else 'Set your requirements'}</div><div class="grid2"><label class="field" for="width">Width (px)<input id="width" type="number" min="1" max="12000" step="1" {'placeholder="Any width"' if check else 'required value="600"'}></label><label class="field" for="height">Height (px)<input id="height" type="number" min="1" max="12000" step="1" {'placeholder="Any height"' if check else 'required value="800"'}></label></div>'''
    if not check: fields+='''<label class="check-label"><input type="checkbox" id="ratio" checked> Link width and height to original ratio</label><label class="field" for="mode">Fit inside the chosen dimensions<select id="mode"><option value="fit">Keep the whole image · white padding</option><option value="crop">Crop to fill · no stretching</option></select></label><div id="crop-settings" class="crop-settings" hidden><p class="hint">Adjust the crop, then prepare again to preview it.</p><label class="field" for="x">Horizontal position: <output id="x-value">50</output>%<input id="x" type="range" min="0" max="100" value="50"></label><label class="field" for="y">Vertical position: <output id="y-value">50</output>%<input id="y" type="range" min="0" max="100" value="50"></label><label class="field" for="zoom">Zoom: <output id="zoom-value">1</output>×<input id="zoom" type="range" min="1" max="4" value="1" step="0.1"></label></div><div class="row"><button id="rotate" type="button">↻ Rotate 90°</button><span id="rotation" class="hint">0° clockwise</span></div>'''
    fields+='<div class="grid2"><label class="field" for="format">'+('Required format' if check else 'Output format')+'<select id="format">'+('<option value="any">Any supported image</option>' if check else '')+'<option value="image/jpeg">JPG / JPEG</option><option value="image/png">PNG</option>'+('<option value="image/webp">WebP</option>' if check else '')+'</select></label><label class="field" for="unit">KB convention<select id="unit"><option value="1000">1 KB = 1,000 bytes</option><option value="1024">1 KB = 1,024 bytes</option></select></label></div><div class="grid2"><label class="field" for="min">Minimum size (KB)<input id="min" type="number" value="0" min="0" step="any" required></label><label class="field" for="max">Maximum size (KB)<input id="max" type="number" value="100" min="0.001" step="any" required></label></div><p class="hint">These are manual settings, not an exam preset. Check the portal’s instructions and KB convention.</p>'
    previews=''
    for side,title in [('before','Original'),('after','Prepared')]:
        previews+=f'<div><div class="preview-head"><span>{title}</span><span>{"01" if side=="before" else "02"}</span></div><div class="preview-area"><img id="{side}" alt="{title} image preview" hidden><div id="{side}-empty"><div class="placeholder">{svg}</div><div class="empty-caption">{"Your image goes here" if side=="before" else "Your result goes here"}</div></div></div><div class="meta" id="{"original-meta" if side=="before" else "result-meta"}">{"Waiting for an image" if side=="before" else "No verified output yet"}</div></div>'
    body=f'''<section class="hero"><div><span class="eyebrow">Made for application day</span><h1>{heading}</h1><p class="intro">{intro}</p></div><aside class="privacy-stamp"><strong>⌁ Local image processing</strong>No document uploads.<br>No account required.</aside></section>{tabs}<div class="workspace"><section class="card"><div class="card-title">{'Check an image' if check else 'Prepare your '+label}<span class="step">MANUAL SETTINGS</span></div><div class="card-body"><div id="drop" class="drop"><div class="upload-icon" aria-hidden="true">↥</div><label for="file"><strong>Choose an image to get started</strong><small>or drag and drop it here</small></label><input class="file-input" id="file" type="file" accept="image/jpeg,image/png,image/webp"><small>JPG, PNG or still WebP · up to 12 MiB / 24 MP</small></div><form id="settings"><fieldset id="controls">{fields}<div class="row actions"><button class="primary" id="run" type="submit" disabled>{'Check requirements' if check else 'Prepare & check image'} →</button><button id="reset" type="button">Reset</button></div></fieldset></form><progress id="progress" max="100" value="0" aria-label="Processing image" hidden></progress><div id="status" class="status" role="status" aria-live="polite">Ready when you are. Your image stays in this browser.</div></div></section><section class="card"><div class="card-title">{'Original file & checks' if check else 'Preview & verification'}<span class="step">BEFORE YOU DOWNLOAD</span></div><div class="card-body"><div class="previews">{previews}</div><div class="verification"><h3>File requirement checklist</h3><ul id="checks" class="checks"></ul><p id="result-note" class="small">Run the check to see measured results.</p><a class="button primary download" id="download" hidden>↓ Download verified image</a><p class="hint">Passing these checks does not guarantee acceptance by an application portal.</p></div></div></section></div><section class="reassurance"><div><h3>01 · Your files stay with you</h3><p>Image processing happens in your browser.</p></div><div><h3>02 · Clear checks, honest results</h3><p>See actual dimensions, format and file size.</p></div><div><h3>03 · Free for the essentials</h3><p>No login, subscriptions or download traps.</p></div></section>{faq}<p class="beta-note">Early release · Manual image tools only. PDF tools and verified application presets are planned. Review every output before submitting.</p>'''
    if check:body=body.replace('<div class="previews">','<div class="previews">').replace('<div><div class="preview-head"><span>Prepared</span>', '<div hidden><div class="preview-head"><span>Prepared</span>')
    page(path,('Image requirement checker' if check else label.capitalize()+' resizer and compressor'),intro,body,tool)
content={
'help':('How to prepare your image','''<ol><li>Read the current instructions on your application portal. Note file format, width, height, size range and any other rules.</li><li>Choose a JPG, PNG or still WebP. We support up to 12 MiB, 24 megapixels, and 12,000 pixels on either side. Output is limited to 8 megapixels.</li><li>Enter the required pixels. Width and height are linked by default. Uncheck the link to enter an exact pair. Fit keeps the whole image with white padding; crop fills the rectangle without stretching.</li><li>Select JPG or PNG and the size range. Choose the correct KB convention: decimal is 1,000 bytes; binary is 1,024 bytes.</li><li>Prepare and check. Review the output carefully, especially facial detail and signature strokes. Download only when the technical checks pass.</li></ol><h2>Known limits</h2><p>JPG quality is searched from 100% to 45% in 1% steps. This threshold is a product safeguard, not a guarantee of legibility. PNG encoding does not use a quality slider. Some ranges cannot be satisfied. We never add padding bytes or secretly change dimensions. Transparency is composited on white for both output formats.</p><p>Modern browser worker canvas support is required. Native image orientation handling is used, but rotated phone images still need device testing. Animated PNG may be decoded as a still frame; avoid animated inputs. PDF, HEIC, SVG, background removal, DPI control, live photo capture and portal-specific validation are not included.</p><h2>For signatures</h2><p>Use a clear source with all strokes visible. Crop away extra space without clipping the signature. Review the final file at its actual size. White padding may be unsuitable for some portals; follow their instructions.</p>'''),
'privacy':('Privacy, in plain language','''<p>Updated 20 October 2026.</p><h2>Image processing</h2><p>The image tools read and process your selected file in your browser using a local worker. The application does not upload or store document contents, filenames or previews on a server. Reset or close the page to release references to the file. Downloads remain wherever your browser saves them. Browser memory management and caches are controlled by your browser.</p><h2>Page requests</h2><p>The hosting provider receives ordinary network requests needed to serve the website, which may include your IP address and browser information. This is distinct from processing your image. Hosting-provider retention is governed by its own policies.</p><h2>Tracking</h2><p>This release adds no analytics, ads, session replay or third-party error reporting. No accounts or cookies are created by the application code. Hosting access controls may operate separately. We will review this notice before adding analytics, advertising or server processing.</p>'''),
'about':('A calmer application workflow','''<p>Application Photo Lab is an early independent project for applicants who need to meet image upload requirements. It combines preparation with explicit technical checks.</p><p>This working label is provisional. It is not affiliated with any government, exam authority, university or recruitment body. No exam presets are currently offered.</p><h2>What comes next</h2><p>After device testing: PDF checking, image-to-PDF and PDF merging, subject to library and security review. PDF compression is not promised. Verified presets will need an official source, cycle and verification date.</p>'''),
 'terms':('Terms of use','''<p>Updated 20 October 2026.</p><p>This early release is provided for image preparation and technical checking. You are responsible for following the current requirements of the receiving portal and reviewing the output for clarity and completeness.</p><p>A passing checklist is not a guarantee of acceptance, identity validity or compliance with every application rule. Keep your originals. Do not rely on this tool as your only copy or as an official source of application requirements.</p><p>Use only files you are entitled to process. There is no affiliation with exam authorities. No payments, accounts or premium services are offered in this release.</p>'''),
 'contact':('Feedback and support','''<p>A public support address has not been configured yet. This early release does not collect messages or documents.</p><p>If you are testing with the project owner, report the browser version, tool name and error message. Do not send personal documents, application numbers or private information. Use a synthetic sample if a reproduction file is needed.</p><p>A verified support channel is a launch requirement before promotion or monetization.</p>''')}
for path,(title,text) in content.items():page(path,title,title+' for Application Photo Lab.',f'<span class="eyebrow">Application Photo Lab</span><h1>{title}</h1><article class="card prose">{text}</article>')
(out/'favicon.svg').write_text('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48"><rect width="48" height="48" rx="10" fill="#255b43"/><path d="M13 23V13h10M25 35h10V25M13 29v6h6M29 13h6v6" fill="none" stroke="#e7f1c9" stroke-width="3"/></svg>')
(out/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+origin+'/sitemap.xml\n')
(out/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+origin+'/'+(p+'/' if p else '')+'</loc></url>' for p in ['', 'signature','checker','help','privacy','about','terms','contact'])+'</urlset>')
(out/'_headers').write_text("/*\n  Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self' blob:; worker-src 'self'; connect-src 'none'; object-src 'none'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'\n  X-Content-Type-Options: nosniff\n  Referrer-Policy: no-referrer\n  Permissions-Policy: camera=(), microphone=(), geolocation=()\n")
